      <!-- Interventions -->
      <div class="section-card" style="grid-column: 1 / -1; background: rgba(16, 185, 129, 0.04); border: 3px solid rgba(16, 185, 129, 0.25);">
        <h2 class="section-title" style="border-bottom-color: var(--accent-teal);">What Works: Tools to Beat Malaria</h2>
        <div class="section-desc" style="color: #6ee7b7;">
