  <script>
    const darkThemeBase = `
  base
    text
      color #f8fafc`;

    const specBurden = `infographic list-grid-badge-card
data
  title The Heavy Toll
  lists
    - label >500,000
      desc Annual deaths
      icon heart beat
    - label Africa
      desc Most affected region
      icon earth
    - label P. falciparum
      desc Deadliest species
      icon caution
theme
  palette #ef4444 #f87171 #fca5a5` + darkThemeBase;

    const specHistorical = `infographic compare-binary-horizontal-simple-fold
data
  title Global Land Coverage of Malaria Risk
  compares
    - label Historically (~1900)
      children
        - label Endemic Area
          value 50%
          icon close circle
    - label Present (~2002)
      children
        - label Endemic Area
          value 27%
          icon check circle
theme
  palette #ef4444 #10b981` + darkThemeBase;

    const specTrends = `infographic chart-line-plain-text
data
  title Global Malaria Deaths
  values
    - label 2000
      value 896000
    - label 2005
      value 810000
    - label 2010
      value 648000
    - label 2015
